**Notes on this optimization:**
- I unrolled the inner `j` (M-dimension) loops by factor=8, which divides... note M=80, and 80/8=10, so factor=8 divides M=80 evenly.
- Array partitioning was added/matched: `mean_local`, `stddev_local`, and `corr_local` now have cyclic factor=8 partitioning on the M dimension to match the unroll factor and avoid port conflicts. `data_local` already had cyclic factor=8 on dim=2.
- The `compute_corr` inner `k` loop is a true floating-point reduction over `acc` with a loop-carried dependency, so I left it unrolled-free to preserve correctness and avoid forcing FP reassociation.
- The `compute_mean` and `compute_stddev` inner loops also carry serial FP reductions over `i`, so they were left unchanged for the same reason.

Looking at this code, the natural place for double buffering is the **load_data** phase paired with subsequent compute, since the whole dataset is loaded into `data_local` before computation begins. By splitting the load into row-tiles and using ping-pong buffers, the load of tile k+1 can overlap with the compute (mean accumulation) of tile k.

I'll create two copies of the `data_local` buffer and alternate between them per row-tile, with `load()` and `compute()` helper functions that accept a flag to select the buffer.

```cpp
#include "correlation.h"
#include <cstring>

// Tile size: number of rows per tile
#define TILE 10

// ---- LOAD helper: stage one tile of rows into selected buffer ----
static void load_tile(double data[N][M],
                      double buf1[TILE][M],
                      double buf2[TILE][M],
                      int tile_base,
                      int rows,
                      bool flag)
{
  for (int ii = 0; ii < TILE; ii++) {
#pragma HLS LOOP_TRIPCOUNT min=TILE max=TILE
    if (ii >= rows) break;
    for (int j = 0; j < M; j++) {
#pragma HLS LOOP_TRIPCOUNT min=M max=M
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
      double v = data[tile_base + ii][j];
      if (flag) buf1[ii][j] = v;
      else      buf2[ii][j] = v;
    }
  }
}

// ---- COMPUTE helper: copy selected tile into full data_local ----
static void compute_tile(double data_local[N][M],
                         double buf1[TILE][M],
                         double buf2[TILE][M],
                         int tile_base,
                         int rows,
                         bool flag)
{
  for (int ii = 0; ii < TILE; ii++) {
#pragma HLS LOOP_TRIPCOUNT min=TILE max=TILE
    if (ii >= rows) break;
    for (int j = 0; j < M; j++) {
#pragma HLS LOOP_TRIPCOUNT min=M max=M
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
      double v = flag ? buf1[ii][j] : buf2[ii][j];
      data_local[tile_base + ii][j] = v;
    }
  }
}

void kernel_correlation( 
			double float_n,
			double data[ N + 0][M + 0],
			double corr[ M + 0][M + 0],
			double mean[ M + 0],
			double stddev[ M + 0])
{
#pragma HLS INTERFACE m_axi port=data   offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=corr   offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=mean   offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=stddev offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=float_n bundle=control
#pragma HLS INTERFACE s_axilite port=data    bundle=control
#pragma HLS INTERFACE s_axilite port=corr    bundle=control
#pragma HLS INTERFACE s_axilite port=mean    bundle=control
#pragma HLS INTERFACE s_axilite port=stddev  bundle=control
#pragma HLS INTERFACE s_axilite port=return  bundle=control

    const int n = N;
    const int m = M;

  int i, j, k;

  double eps = 0.1;

  // ---- Local tile buffers ----
  double data_local[N][M];
#pragma HLS ARRAY_PARTITION variable=data_local cyclic factor=8 dim=2
  double mean_local[M];
#pragma HLS ARRAY_PARTITION variable=mean_local cyclic factor=8 dim=1
  double stddev_local[M];
#pragma HLS ARRAY_PARTITION variable=stddev_local cyclic factor=8 dim=1
  double corr_local[M][M];
#pragma HLS ARRAY_PARTITION variable=corr_local cyclic factor=8 dim=2

  // ---- Double buffers (ping-pong) for the LOAD phase ----
  double data_buf1[TILE][M];
#pragma HLS ARRAY_PARTITION variable=data_buf1 cyclic factor=8 dim=2
  double data_buf2[TILE][M];
#pragma HLS ARRAY_PARTITION variable=data_buf2 cyclic factor=8 dim=2

  // ---- LOAD phase with double buffering: overlap load(k+1) and compute(k) ----
  const int num_tiles = (n + TILE - 1) / TILE;

  load_double_buffer:
  for (int t = 0; t < num_tiles + 1; t++) {
#pragma HLS LOOP_TRIPCOUNT min=11 max=11
    bool load_flag = (t % 2 == 0);            // buffer to load INTO this iteration
    bool comp_flag = ((t - 1) % 2 == 0);      // buffer to consume from previous load

    int load_base = t * TILE;
    int load_rows = (load_base + TILE <= n) ? TILE : (n - load_base);
    if (load_base >= n) load_rows = 0;

    int comp_base = (t - 1) * TILE;
    int comp_rows = (comp_base + TILE <= n) ? TILE : (n - comp_base);
    if (t == 0 || comp_base >= n) comp_rows = 0;

    // Load tile t (producer) and compute/copy tile t-1 (consumer) overlap
    if (load_rows > 0)
      load_tile(data, data_buf1, data_buf2, load_base, load_rows, load_flag);

    if (comp_rows > 0)
      compute_tile(data_local, data_buf1, data_buf2, comp_base, comp_rows, comp_flag);
  }

  // ---- COMPUTE phase: mean ----
  compute_mean:
  for (j = 0; j < m; j++)
    {
#pragma HLS LOOP_TRIPCOUNT min=M max=M
      mean_local[j] = 0.0;
      for (i = 0; i < n; i++) {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
	mean_local[j] += data_local[i][j];
      }
      mean_local[j] /= float_n;
    }

  // ---- COMPUTE phase: stddev ----
  compute_stddev:
   for (j = 0; j < m; j++)
    {
#pragma HLS LOOP_TRIPCOUNT min=M max=M
      stddev_local[j] = 0.0;
      for (i = 0; i < n; i++) {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
        stddev_local[j] += (data_local[i][j] - mean_local[j]) * (data_local[i][j] - mean_local[j]);
      }
      stddev_local[j] /= float_n;
      stddev_local[j] = sqrt(stddev_local[j]);

      stddev_local[j] = stddev_local[j] <= eps ? 1.0 : stddev_local[j];
    }

  // ---- COMPUTE phase: center and normalize data ----
  compute_normalize:
  for (i = 0; i < n; i++) {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
    for (j = 0; j < m; j++)
      {
#pragma HLS LOOP_TRIPCOUNT min=M max=M
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
        data_local[i][j] -= mean_local[j];
        data_local[i][j] /= sqrt(float_n) * stddev_local[j];
      }
  }

  // ---- COMPUTE phase: correlation ----
  compute_corr:
  for (i = 0; i < m-1; i++)
    {
#pragma HLS LOOP_TRIPCOUNT min=M max=M
      corr_local[i][i] = 1.0;
      for (j = i+1; j < m; j++)
        {
#pragma HLS LOOP_TRIPCOUNT min=M max=M
          double acc = 0.0;
          for (k = 0; k < n; k++) {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
            acc += (data_local[k][i] * data_local[k][j]);
          }
          corr_local[i][j] = acc;
          corr_local[j][i] = acc;
        }
    }
  corr_local[m-1][m-1] = 1.0;

  // ---- STORE phase: write results back to global memory ----
  store_mean:
  for (j = 0; j < m; j++) {
#pragma HLS LOOP_TRIPCOUNT min=M max=M
#pragma HLS PIPELINE II=1
    mean[j] = mean_local[j];
    stddev[j] = stddev_local[j];
  }

  store_data:
  for (i = 0; i < n; i++) {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
    for (j = 0; j < m; j++) {
#pragma HLS LOOP_TRIPCOUNT min=M max=M
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
      data[i][j] = data_local[i][j];
    }
  }

  store_corr:
  for (i = 0; i < m; i++) {
#pragma HLS LOOP_TRIPCOUNT min=M max=M
    for (j = 0; j < m; j++) {
#pragma HLS LOOP_TRIPCOUNT min=M max=M
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
      corr[i][j] = corr_local[i][j];
    }
  }

}
```

**What changed (double buffering only):**

- Added two ping-pong tile buffers `data_buf1` and `data_buf2` (each `TILE x M`), partitioned to match the existing factor-8 scheme.
- Created `load_tile()` and `compute_tile()` helper functions that each take a `flag` parameter to select which physical buffer to read/write.
- The new `load_double_buffer` loop runs `num_tiles + 1` iterations. On iteration `t`, it **loads** tile `t` into the buffer chosen by `load_flag` while **consuming** tile `t-1` from the other buffer (`comp_flag`). The extra `+1` iteration drains the final tile, preserving last-tile behavior; the `t==0` guard preserves first-tile behavior (no consume on the very first iteration).
- Because the producer (`load_tile`) and consumer (`compute_tile`) on a given iteration touch *different* physical buffers, their accesses are independent and the scheduler can overlap the global-memory load of tile k+1 with the copy of tile k.
- All existing pipeline/partition/unroll pragmas in the compute and store phases are unchanged.

Looking at this code, I need to apply memory coalescing by converting the `double*`-style 2D array arguments to wide bus pointers and using helper functions for burst transfers.

